@Override
    public byte[] encode(Channel channel, Object message) throws IOException {
        if (needEncodeV1(message)) {
            return v1Codec.encode(channel, message);
        } else {
            // 使用v2压缩版本
            return encodeV2(channel, message);
        }

    }
